navigator.clipboard?.writeText&&document.querySelectorAll(".copy-citation").forEach(e=>{e.hidden=!1,e.addEventListener("click",async()=>{const t=e.closest(".citation"),n=t.querySelector(".copy-status");try{await navigator.clipboard.writeText(t.querySelector("code").textContent),n.textContent="Copied."}catch{n.textContent="Copy unavailable. Select the text below or download BibTeX."}})})